import {bins,summarize,filterRows,sortRows,civilTime} from './history-core.mjs';
const $=q=>document.querySelector(q);const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=n=>Number(n).toLocaleString('en-CA');
const state={index:null,cache:new Map(),rows:[],sorted:[],summary:null,page:0,token:0};const size=100;
const flags=['Delay over 1 hour','Duplicate candidate','Missing destination','Missing day type','Invalid location','Invalid required fields'];
const delay=v=>v===null?'—':Math.abs(v)<1?'0:00':`${v<0?'−':'+'}${Math.floor(Math.abs(Math.round(v))/60)}:${String(Math.abs(Math.round(v))%60).padStart(2,'0')}`;
async function json(url){const r=await fetch(url);if(!r.ok)throw new Error(`Data request failed (${r.status}).`);return r.json()}
function busy(yes){$('#apply').disabled=yes;$('#all-dates').disabled=yes;$('.history-filters').setAttribute('aria-busy',String(yes));$('#apply').textContent=yes?'Loading…':'Apply filters'}
async function apply(){const start=$('#start').value,end=$('#end').value;if(!start||!end||start>end){$('#history-status').className='history-error';$('#history-status').textContent='Choose a valid date range with From on or before Through.';return null}const token=++state.token;const selection={stop:$('#stop').value,dest:$('#dest').value,exclude:$('#exclude').checked};busy(true);$('#history-status').className='';$('#history-status').textContent='Loading selected dates…';try{const dates=state.index.dates.filter(d=>d.date>=start&&d.date<=end);let next=0;await Promise.all(Array.from({length:Math.min(6,dates.length)},async()=>{while(next<dates.length){const day=dates[next++].date;if(!state.cache.has(day)){const data=await json(`history/${day}.json`);if(!Array.isArray(data))throw new Error('Invalid historical data.');state.cache.set(day,data)}}}));if(token!==state.token)return null;await new Promise(resolve=>requestAnimationFrame(resolve));let rows=[];for(const {date} of dates){for(const v of state.cache.get(date))rows.push({date,v})}rows=filterRows(rows,selection);state.rows=rows;state.summary=summarize(rows);state.page=0;state.sorted=sortRows(rows,$('#sort').value);render();const calendarDays=Math.round((Date.parse(end)-Date.parse(start))/86400000)+1;$('#history-status').textContent=`${num(rows.length)} records · ${state.summary.days.length} dates with valid matching records in ${calendarDays} calendar days. ${num(state.summary.flagged)} flagged records included.`;$('#records-description').textContent=`${start} through ${end} · ${selection.exclude?'flagged records excluded':'all quality levels'} · times in Winnipeg`;const url=new URL(location.href);url.searchParams.set('from',start);url.searchParams.set('to',end);for(const [key,value] of Object.entries(selection)){if(value!==''&&value!==false)url.searchParams.set(key,String(value));else url.searchParams.delete(key)}history.replaceState(null,'',url);return {records:rows.length,validDelays:state.summary.valid,medianDelaySeconds:state.summary.median,within120:state.summary.within}}catch(error){if(token===state.token){$('#history-status').className='history-error';$('#history-status').textContent=`${error.message} Try Apply filters again. Any previous results remain below.`}return null}finally{if(token===state.token)busy(false)}}
function render(){const s=state.summary;$('#history-stats').innerHTML=`<div class="stat"><span class="label">Recorded departures</span><strong class="value">${num(s.records)}</strong><span class="hint">${num(s.flagged)} with quality flags</span></div><div class="stat"><span class="label">Median delay</span><strong class="value">${delay(s.median)}</strong><span class="hint">Positive = late · negative = early</span></div><div class="stat"><span class="label">Within ±2 minutes</span><strong class="value">${s.within===null?'—':(s.within*100).toFixed(1)+'%'}</strong><span class="hint">${num(s.valid)} valid delay values</span></div>`;renderChart();const max=Math.max(1,...s.counts);$('#distribution').innerHTML=bins.map(([, ,label],i)=>`<div class="distribution-row"><span>${h(label)}</span><span class="distribution-track"><span class="distribution-fill ${i<3?'early':i>4?'late':''}" style="display:block;width:${s.counts[i]/max*100}%"></span></span><strong title="${num(s.counts[i])} departures">${s.valid?(s.counts[i]/s.valid*100).toFixed(0)+'%':'—'}</strong></div>`).join('');renderTable()}
function renderChart(){const rows=state.summary.days;if(!rows.length){$('#daily-chart').innerHTML='<div class="history-empty">No valid delays match these filters.</div>';return}const width=Math.max(280,$('#daily-chart').clientWidth-32),height=246,p={l:40,r:17,t:12,b:42};const first=Date.parse($('#start').value),last=Date.parse($('#end').value);const x=date=>p.l+(first===last ? .5 : (Date.parse(date)-first)/(last-first))*(width-p.l-p.r),y=percent=>p.t+(100-percent)/100*(height-p.t-p.b);let grid='';for(const v of [0,25,50,75,100])grid+=`<line x1="${p.l}" x2="${width-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#e5edf5"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end">${v}%</text>`;let path='',previous=null;for(const row of rows){path+=`${previous!==null&&Date.parse(row.date)-previous===86400000?'L':'M'}${x(row.date)},${y(row.within/row.n*100)} `;previous=Date.parse(row.date)}const labels=[...new Set([0,Math.floor((rows.length-1)/2),rows.length-1])].map(i=>`<text x="${x(rows[i].date)}" y="${height-14}" text-anchor="middle">${rows[i].date.slice(5)}</text>`).join('');$('#daily-chart').innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Daily percentage of departures within two minutes of schedule; missing dates are gaps.">${grid}<path d="${path}" fill="none" stroke="#185ccb" stroke-width="2.5"/>${rows.map(r=>`<circle cx="${x(r.date)}" cy="${y(r.within/r.n*100)}" r="3.5" fill="#185ccb"><title>${r.date}: ${(r.within/r.n*100).toFixed(1)}% of ${num(r.n)} departures</title></circle>`).join('')}${labels}</svg>`}
function renderTable(){const pages=Math.max(1,Math.ceil(state.sorted.length/size));state.page=Math.min(state.page,pages-1);const start=state.page*size;$('#history-records').innerHTML=state.sorted.slice(start,start+size).map(({date,v})=>{const stop=state.index.stops[v[1]],quality=flags.filter((_,i)=>(v[5]&(1<<i))!==0);const actual=v[4]===null?'—':civilTime(date,v[3]+v[4]);return `<tr><td>${h(civilTime(date,v[3]))}</td><td>${h(stop?.number||'Unknown')}<small style="display:block;color:var(--muted);font-size:12px">${h(stop?.name||'')}</small></td><td>${h(state.index.destinations[v[2]]||'Unknown')}</td><td>${h(actual)}</td><td><span class="delay ${v[4]===null?'':Math.abs(v[4])<=120?'near':v[4]>0?'late':'early'}">${delay(v[4])}</span></td><td class="quality-cell ${quality.length?'flag':''}">${quality.length?h(quality.join(' · ')):'—'}</td><td>${h(v[0])}</td></tr>`}).join('')||'<tr><td colspan="7" class="history-empty">No records match these filters.</td></tr>';$('#page-info').textContent=state.sorted.length?`${num(start+1)}–${num(Math.min(start+size,state.sorted.length))} of ${num(state.sorted.length)}`:'0 records';$('#previous').disabled=state.page===0;$('#next').disabled=state.page+1>=pages}
$('#filters').onsubmit=e=>{e.preventDefault();apply()};$('#all-dates').onclick=()=>{$('#start').value=state.index.dates[0].date;$('#end').value=state.index.dates.at(-1).date;apply()};$('#sort').onchange=()=>{state.sorted=sortRows(state.rows,$('#sort').value);state.page=0;renderTable()};$('#previous').onclick=()=>{state.page--;renderTable();$('.history-table').scrollTop=0};$('#next').onclick=()=>{state.page++;renderTable();$('.history-table').scrollTop=0};
try{state.index=await json('history/index.json');const i=state.index,first=i.dates[0].date,last=i.dates.at(-1).date;$('#history-coverage').textContent=`${num(i.records)} departures · ${first} to ${last}`;$('#history-source').textContent=i.supplementalSources?.length?`Original file + City updates through ${last}`:'Source file downloaded September 13, 2026';$('#stop').innerHTML='<option value="">All stops</option>'+i.stops.map((s,n)=>`<option value="${n}">${h(s.number)}${s.name?' · '+h(s.name):''}</option>`).join('');$('#dest').innerHTML='<option value="">All destinations</option>'+i.destinations.map((d,n)=>`<option value="${n}">${h(d)}</option>`).join('');for(const name of ['start','end']){$('#'+name).min=first;$('#'+name).max=last}const params=new URL(location.href).searchParams;$('#start').value=params.get('from')||i.dates[Math.max(0,i.dates.length-7)].date;$('#end').value=params.get('to')||last;for(const name of ['stop','dest'])if(params.has(name)&&[...$('#'+name).options].some(o=>o.value===params.get(name)))$('#'+name).value=params.get(name);$('#exclude').checked=params.get('exclude')==='true';await apply()}catch(error){$('#history-status').className='history-error';$('#history-status').textContent=`Historical data couldn’t be loaded: ${error.message} Reload this page to retry.`;busy(true)}
if(document.modelContext?.registerTool&&state.index){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{await document.modelContext.registerTool({name:'filter_historical_departures',title:'Filter historical departure records',description:'Apply a date range and optional stop number, destination and quality filter to the visible historical dashboard.',inputSchema:{type:'object',properties:{from:{type:'string'},to:{type:'string'},stopNumber:{type:'string'},destination:{type:'string'},excludeFlagged:{type:'boolean'}},required:['from','to'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).some(k=>!['from','to','stopNumber','destination','excludeFlagged'].includes(k))||typeof input.from!=='string'||typeof input.to!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(input.from)||!/^\d{4}-\d{2}-\d{2}$/.test(input.to)||input.from>input.to||input.from<state.index.dates[0].date||input.to>state.index.dates.at(-1).date)throw new Error('Provide a valid date range within the available history.');if(input.excludeFlagged!==undefined&&typeof input.excludeFlagged!=='boolean')throw new Error('excludeFlagged must be boolean.');const stop=input.stopNumber===undefined?'':state.index.stops.findIndex(s=>s.number===input.stopNumber);const dest=input.destination===undefined?'':state.index.destinations.indexOf(input.destination);if(stop===-1||dest===-1)throw new Error('Unknown stop or destination.');$('#start').value=input.from;$('#end').value=input.to;$('#stop').value=String(stop);$('#dest').value=String(dest);$('#exclude').checked=!!input.excludeFlagged;const result=await apply();if(!result)throw new Error('The requested historical data could not be loaded.');return result}},{signal:lifecycle.signal})}catch{/* Optional progressive enhancement; all filters work without it. */}}
